# Run from the package root after data-raw/dat/build_dat.R and 54b:  Rscript data-raw/qa/62_st_louis_section.R
# Writes the section "A worked example: the St. Louis tornado of 16 May 2025" of data-raw/known_issues.md (between <!-- st-louis:start --> and <!-- st-louis:end -->).
# All numbers are read from the data and the saved results of the QA scripts.
suppressMessages({library(sf); library(dplyr)}); source("data-raw/qa/helpers.R"); for (f in list.files("data", pattern = "\\.rda$", full.names = TRUE)) load(f)
f0 <- function(x) formatC(x, format = "d", big.mark = ","); id <- "2025_2505161339-01"
tt <- st_drop_geometry(tornado_tracks); t1 <- tt[tt$tornado_id == id, ]; ex <- tornado_exposure[tornado_exposure$tornado_id == id, ]
lk <- tornado_dat_link[tornado_dat_link$tornado_id == id, ]; lk <- lk[order(lk$dat_line_id), ]; dl <- st_drop_geometry(dat_lines)[match(lk$dat_line_id, dat_lines$objectid), ]
rr <- spc_records[spc_records$yr == 2025 & grepl("^2505161339", spc_records$om), ]; rr <- rr[order(rr$om), ]
pl <- dat_polygon_line_link[dat_polygon_line_link$dat_line_id %in% lk$dat_line_id & dat_polygon_line_link$line_share_in_polygon > 0, ]; dp <- st_drop_geometry(dat_polygons)[match(unique(pl$dat_polygon_id), dat_polygons$objectid), ]
nc <- readRDS(qa_out("ncei_comparison.rds")); ev <- nc$R$st_louis_events
md <- function(df) { df[] <- lapply(df, as.character); paste(c(paste0("| ", paste(names(df), collapse = " | "), " |"), paste0("|", paste(rep("---", ncol(df)), collapse = "|"), "|"), apply(df, 1, function(r) paste0("| ", paste(r, collapse = " | "), " |"))), collapse = "\n") }
ex <- ex[order(!ex$spc_exposed, ex$ZCTA), ]; npt <- function(x) rowSums(x[, grep("^dat_points_", names(x))])
ex_tab <- data.frame(ZCTA = ex$ZCTA, `SPC line` = ifelse(ex$spc_exposed, sprintf("%.2f km (share %.3f)", ex$line_km_in_zcta, ex$line_share_of_tornado), "no"), `NWS polygons` = ifelse(ex$dat_exposed, sprintf("%.4f of the land (EF3 %.4f, EF1 %.4f)", ex$dat_area_share, ex$dat_area_share_ef3, ex$dat_area_share_ef1), "no"), Residents = f0(round(ex$dat_pop_affected)), Points = npt(ex), `Boundary distance` = sprintf("%.2f km", ex$boundary_dist_km), check.names = FALSE)
ef <- function(x) ifelse(is.na(x), "unknown", x)
line_txt <- paste0(vapply(seq_len(nrow(lk)), function(i) paste0("DAT line ", lk$dat_line_id[i], " (", dl$efscale[i], ", ", sprintf("%.2f", dl$length[i]), " miles, width ", f0(dl$width[i]), " yards; rule `", lk$rule[i], "`, index-aligned distance ", sprintf("%.2f", lk$index_aligned_dist_km[i]), " km, one-sided distance ", sprintf("%.2f", lk$one_sided_dist_km[i]), " km, length ratio ", sprintf("%.2f", lk$length_ratio[i]), ")"), ""), collapse = "; ")
txt <- c("<!-- st-louis:start -->", "## A worked example: the St. Louis tornado of 16 May 2025", "",
 paste0("SPC's 2025 file (released 24 April 2026) has one whole-track record for the tornado, `", id, "`: ", sprintf("%.2f", t1$len_mi), " miles, a width of ", f0(t1$wid_yd), " yards, rating ", t1$magnitude, ", ", t1$total_injury, " injuries and ", t1$total_fatality, " deaths, from ", sprintf("%.4f", t1$slat), ", ", sprintf("%.4f", t1$slon), " to ", sprintf("%.4f", t1$elat), ", ", sprintf("%.4f", t1$elon),
   " (Missouri into Illinois). `spc_records` also holds the other rows of the record: ", paste0("`", rr$om, "` (sg ", rr$sg, ", ", rr$st, ", ", sprintf("%.2f", rr$len), " miles, rating ", rr$mag, ")", collapse = "; "), "."),
 "",
 "The National Weather Service surveyed it as two separate tornadoes from one storm circulation: an EF3 that lifted just north of Granite City, Illinois, and an EF1 that touched down just south of that point ([Updated Damage Assessment for May 16, 2025 St. Louis Tornado](https://www.weather.gov/lsx/STLTornado); reported by [STLPR on 15 May 2026](https://www.stlpr.org/news-briefs/2026-05-15/may-16-tornado-reached-1-8-miles-wide)). SPC's file of 24 April 2026 predates that update of 15 May 2026, so it holds one record with rating 2.",
 "",
 paste0("**What the package holds.** The DAT lines are in `dat_lines` and are both linked to the one SPC record in `tornado_dat_link`: ", line_txt, ". Relationship `", unique(lk$relationship), "`. The damage polygons that touch these lines (`dat_polygon_line_link`, `line_share_in_polygon` above 0) number ", f0(nrow(dp)), " (ratings ", paste(names(table(ef(dp$efscale))), table(ef(dp$efscale)), collapse = ", "), "). `map_exposure()` draws the SPC line over the two DAT tornadoes (the call is in the README)."),
 "",
 paste0("**Exposure.** The SPC line (", sprintf("%.1f", t1$line_km), " km; ", sprintf("%.1f", t1$line_km_outside_zcta), " km of it lie in no ZCTA) crosses ", sum(ex$spc_exposed), " ZCTAs (", sum(ex$spc_exposed & substr(ex$ZCTA, 1, 2) == "63"), " in Missouri, ", sum(ex$spc_exposed & substr(ex$ZCTA, 1, 2) == "62"), " in Illinois). The linked NWS polygons (EF1 and EF3) cover land in ", sum(ex$dat_exposed), " ZCTAs; ", sum(ex$spc_exposed & ex$dat_exposed), " are exposed by both, ", sum(ex$spc_exposed & !ex$dat_exposed), " only by the SPC line and ", sum(!ex$spc_exposed), " only by the NWS polygons (`spc_exposed` is `FALSE` there, and their SPC columns are `NA` except the distances). The polygons cover ", sprintf("%.2f", 100 * sum(ex$dat_area_share * ex$zcta_land_shape_area_m2) / sum(ex$zcta_land_shape_area_m2[ex$dat_exposed])), " percent of the land of the ZCTAs they reach, and ", f0(round(sum(ex$dat_pop_affected))), " residents (EF3 part: ", f0(round(sum(ex$dat_pop_ef3))), ", EF1 part: ", f0(round(sum(ex$dat_pop_ef1))), "), by the highest rating that covers each part. ", f0(sum(ex$dat_points_ef0 + ex$dat_points_ef1 + ex$dat_points_ef2 + ex$dat_points_ef3 + ex$dat_points_ef4 + ex$dat_points_ef5 + ex$dat_points_efu + ex$dat_points_wind + ex$dat_points_other)), " NWS damage points lie in these ZCTAs within a day. The table gives each ZCTA:"),
 "", md(ex_tab), "",
 if (!is.null(ev)) paste0("**NCEI.** NCEI's Storm Events database has three events for it: ", paste0("event ", ev$EVENT_ID, " (", ev$STATE, ", ", ev$TOR_F_SCALE, ", ", ev$TOR_LENGTH, " miles, ", ev$TOR_WIDTH, " yards)", collapse = "; "), ". NCEI is built from the same NWS Storm Data as SPC and is not independent."),
 "",
 "A check of this case is in `data-raw/qa/check_data_integrity.R`.", "<!-- st-louis:end -->")
kl <- readLines("data-raw/known_issues.md"); a <- grep("<!-- st-louis:start -->", kl, fixed = TRUE); b <- grep("<!-- st-louis:end -->", kl, fixed = TRUE)
kl <- if (length(a) && length(b)) c(kl[seq_len(a - 1)], txt, kl[-seq_len(b)]) else append(kl, c(txt, ""), after = grep("^## Point tracks|^<!-- no-end-point:start -->", kl)[1] - 1)
writeLines(kl, "data-raw/known_issues.md"); cat(txt, sep = "\n")
